//! Regenerates the protobuf and gRPC code checked in under `garage-plugin/src/generated/`.
//!
//! Checked in rather than generated by a build script so that neither Cargo nor Bazel needs
//! `protoc` to build a plugin. Run it after editing `proto/garage_plugin.proto`:
//!
//! ```sh
//! cargo run -p protogen
//! ```
//!
//! CI runs it and fails when the result differs from what is checked in.

use std::path::PathBuf;

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let workspace =
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).parent().expect("protogen lives in the workspace").to_path_buf();
    let proto_dir = workspace.parent().expect("rust/ lives in the repository").join("proto");
    let proto = proto_dir.join("garage_plugin.proto");
    let messages = workspace.join("garage-plugin/src/generated/messages");
    let services = workspace.join("garage-plugin/src/generated/services");
    std::fs::create_dir_all(&messages)?;
    std::fs::create_dir_all(&services)?;

    // The messages alone, for the in-process C ABI, which links no gRPC.
    tonic_prost_build::configure()
        .build_client(false)
        .build_server(false)
        .out_dir(&messages)
        .compile_protos(&[&proto], &[&proto_dir])?;

    // The client and server, over the messages above.
    tonic_prost_build::configure()
        .build_client(true)
        .build_server(true)
        .extern_path(".garage.plugin.v1", "crate::proto")
        .out_dir(&services)
        .compile_protos(&[&proto], &[&proto_dir])?;
    Ok(())
}
